'use client'

import * as React from 'react'
import { Slot } from 'radix-ui'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Spinner } from '@/registry/satin/ui/spinner'

/**
 * Button, 1:1 with the uiKit `button` component set (10:1838): five styles, four sizes
 * xs / md / lg / xl (24 / 28 / 32 / 36), Default or Rounded shape, and an icon-only form.
 *
 * Solid styles (primary, destructive, inverse) are a border in the style's `border`
 * token, an outer ring of the same width in the current background and a 0 3 6 drop shadow (gone when
 * pressed); no inner glow. Focus adds a 2px `action/focus-ring` spread; disabled
 * is the default look at 50% opacity. Icons take the label colour on solid styles and
 * text/muted on secondary and tertiary.
 *
 * Shadows are written as plain box-shadow, not Tailwind's shadow utilities: those compose
 * five custom properties, and a browser that drops one of them drops the whole shadow.
 *
 * States use the satin-hover / satin-focus / satin-pressed variants (styles/index.css):
 * the real pseudo-classes, or `data-force="hover" | "focus" | "pressed"` for state sheets.
 * An open menu's trigger looks pressed, which hides the ring; with keyboard focus on it the
 * `[aria-haspopup][aria-expanded=true]:focus-visible` rules bring the ring back.
 */
const buttonVariants = cva(
  [
    'sa:inline-flex sa:shrink-0 sa:items-center sa:justify-center sa:overflow-clip sa:font-medium sa:whitespace-nowrap sa:select-none',
    'sa:transition-[background-color,border-color,color,box-shadow,transform] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
    // A menu or popover trigger snaps back to full size the moment it opens (no scale, no
    // transform transition), so the menu measures the button's real edge and never jumps.
    'sa:not-aria-expanded:active:scale-[0.97] sa:aria-expanded:[transition-property:background-color,border-color,color,box-shadow]',
    'sa:disabled:pointer-events-none sa:disabled:opacity-50',
    // Focus: the ring 2px off the button, so it reads against the page whatever the fill.
    // (outline-solid too: the base focus rule sets the outline style to none.)
    'sa:satin-focus:outline-2 sa:satin-focus:outline-solid sa:satin-focus:outline-offset-2 sa:satin-focus:outline-action-focus-ring',
    'sa:[&_svg]:pointer-events-none sa:[&_svg]:shrink-0',
    // Figma icons are 1.25px at 16 and 1.09px at 14; on Iconoir's 24 grid both are 1.875.
    'sa:[&_svg]:[stroke-width:1.875]',
  ],
  {
    variants: {
      variant: {
        primary: [
          'sa:border sa:border-strong sa:border-action-primary-border sa:bg-action-primary-bg sa:text-action-primary-fg',
          'sa:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-primary-bg),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-hover:bg-action-primary-bg-hover sa:satin-hover:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-primary-bg-hover),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-focus:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-primary-bg),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-pressed:bg-action-primary-bg-pressed sa:satin-pressed:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-primary-bg-pressed)]',
        ],
        destructive: [
          'sa:border sa:border-strong sa:border-action-destructive-border sa:bg-action-destructive-bg sa:text-text-on-solid',
          'sa:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-destructive-bg),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-hover:bg-action-destructive-bg-hover sa:satin-hover:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-destructive-bg-hover),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-focus:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-destructive-bg),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-pressed:bg-action-destructive-bg-pressed sa:satin-pressed:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-destructive-bg-pressed)]',
        ],
        inverse: [
          'sa:border sa:border-strong sa:border-action-inverse-border sa:bg-action-inverse-bg sa:text-text-on-inverse',
          'sa:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-inverse-bg),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-hover:bg-action-inverse-bg-hover sa:satin-hover:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-inverse-bg-hover),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-focus:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-inverse-bg),0_3px_6px_0_var(--sa-action-primary-shadow)]',
          'sa:satin-pressed:bg-action-inverse-bg-pressed sa:satin-pressed:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-action-inverse-bg-pressed)]',
        ],
        // The outline is a ring outside the box, like the filled variants' ring, so all of
        // them read the same height; the border underneath takes the fill.
        secondary: [
          'sa:border sa:border-strong sa:border-transparent sa:bg-bg-popover sa:text-text-default sa:[&_svg]:text-text-muted',
          'sa:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-border-default),0_1px_2px_1px_var(--sa-effect-shadow-xs)]',
          'sa:disabled:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-border-strong)]',
          'sa:satin-hover:bg-action-secondary-bg-hover sa:satin-hover:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-border-strong),0_1px_2px_1px_var(--sa-effect-shadow-xs)]',
          'sa:satin-focus:bg-bg-popover sa:satin-focus:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-border-strong),0_1px_2px_1px_var(--sa-effect-shadow-xs)]',
          'sa:satin-pressed:bg-action-secondary-bg-pressed sa:satin-pressed:[box-shadow:0_0_0_var(--sa-border-width-strong)_var(--sa-border-strong)]',
        ],
        tertiary: [
          'sa:bg-transparent sa:text-text-default sa:[&_svg]:text-text-muted',
          'sa:satin-hover:bg-bg-hover',
          'sa:satin-focus:bg-bg-hover sa:satin-focus:[box-shadow:none]',
          'sa:satin-pressed:bg-bg-pressed',
        ],
      },
      size: {
        xs: 'sa:h-control-height-xs sa:gap-1 sa:px-2 sa:text-sm sa:[&_svg]:size-icon-size-sm',
        md: 'sa:h-control-height sa:gap-1.5 sa:px-2.5 sa:text-sm sa:[&_svg]:size-icon-size',
        lg: 'sa:h-control-height-lg sa:gap-1.5 sa:px-3 sa:text-sm sa:[&_svg]:size-icon-size',
        xl: 'sa:h-control-height-xl sa:gap-2 sa:px-3 sa:text-base sa:[&_svg]:size-icon-size',
      },
      shape: {
        default: '',
        rounded: 'sa:rounded-pill',
      },
      iconOnly: {
        true: 'sa:px-0',
        false: '',
      },
    },
    compoundVariants: [
      // Default shape: the radius grows with the size (8 / 10 / 10 / 12).
      { shape: 'default', size: 'xs', className: 'sa:rounded-md' },
      { shape: 'default', size: 'md', className: 'sa:rounded-lg' },
      { shape: 'default', size: 'lg', className: 'sa:rounded-lg' },
      { shape: 'default', size: 'xl', className: 'sa:rounded-xl' },
      { iconOnly: true, size: 'xs', className: 'sa:w-control-height-xs' },
      { iconOnly: true, size: 'md', className: 'sa:w-control-height' },
      { iconOnly: true, size: 'lg', className: 'sa:w-control-height-lg' },
      { iconOnly: true, size: 'xl', className: 'sa:w-control-height-xl' },
    ],
    defaultVariants: { variant: 'primary', size: 'md', shape: 'default', iconOnly: false },
  },
)

export interface ButtonProps
  extends React.ComponentProps<'button'>,
    VariantProps<typeof buttonVariants> {
  /** Render the child element (a link, say) with the button's styles instead of a `<button>`. */
  asChild?: boolean
  /**
   * Busy: a Spinner takes the middle and the label and icons turn invisible but keep their room,
   * so the button doesn't change width. Clicks (and Enter in a form) do nothing; the button
   * keeps its focus and looks, with `aria-busy` and `aria-disabled` for screen readers.
   */
  loading?: boolean
}

/**
 * What a ButtonGroup hands its buttons: the variant, size and shape they take unless they set
 * their own. Lives here so Button reads it without importing the group.
 */
export type ButtonDefaults = Pick<VariantProps<typeof buttonVariants>, 'variant' | 'size' | 'shape'>

export const ButtonDefaultsContext = React.createContext<ButtonDefaults | null>(null)

export function Button({ className, variant, size, shape, iconOnly, asChild = false, loading = false, type, onClick, children, 'aria-disabled': ariaDisabled, ...props }: ButtonProps) {
  const Comp = asChild ? Slot.Root : 'button'
  const group = React.useContext(ButtonDefaultsContext)
  const resolved = variant ?? group?.variant ?? 'primary'
  return (
    <Comp
      data-slot="button"
      data-variant={resolved}
      type={asChild ? undefined : (type ?? 'button')}
      aria-busy={loading || undefined}
      aria-disabled={loading || ariaDisabled || undefined}
      data-loading={loading || undefined}
      className={cn(
        buttonVariants({ variant: resolved, size: size ?? group?.size, shape: shape ?? group?.shape, iconOnly }),
        loading && 'sa:relative sa:cursor-progress',
        className,
      )}
      onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
        if (loading) {
          event.preventDefault()
          return
        }
        onClick?.(event)
      }}
      {...props}
    >
      {loading && !asChild ? (
        <>
          <span className="sa:invisible sa:contents">{children}</span>
          <span className="sa:absolute sa:inset-0 sa:grid sa:place-items-center">
            <Spinner size={(size ?? group?.size) === 'xs' ? 'sm' : 'md'} label={null} />
          </span>
        </>
      ) : (
        children
      )}
    </Comp>
  )
}

export { buttonVariants }
